export const ClinicsAuditListResponse = zod.object({
  next: zod.string().url().nullish(),
  previous: zod.string().url().nullish(),
  results: zod.array(
    zod
      .object({
        action: zod.string(),
        actor_id: zod.string().uuid().nullable(),
        after: zod.union([zod.unknown(), zod.null()]),
        before: zod.union([zod.unknown(), zod.null()]),
        created_at: zod.coerce.date(),
        entity_id: zod.string(),
        entity_type: zod.string(),
        hash: zod.string(),
        id: zod.number(),
        prev_hash: zod.string(),
        request_id: zod.string(),
      })
      .describe(
        "Read-only projection of one audit row.\n\n``ip_hash`` is a salted digest, not an address, but it is still omitted:\nthe endpoint's job is to show \*what changed\*, and a stable per-IP hash is a\ntracking identifier. ``hash``\/``prev_hash`` are included so a client can\nspot-check the chain without a second endpoint.",
      ),
  ),
});

